"""Disposable Docker API + worker with a kernel-enforced read-only source fixture."""
import json
import os
from pathlib import Path
import shutil
import signal
import subprocess
import time
import urllib.request
import uuid


def docker(*args, input=None):
    result = subprocess.run(['docker', *args], input=input, text=True, capture_output=True)
    if result.returncode:
        raise RuntimeError(result.stderr)
    return result.stdout.strip()


def main():
    root = Path(os.environ['JUANZHAN_E2E_SOURCE_ROOT'])
    # This path is generated by the Playwright config, never supplied by production.
    if root.parent != Path('/tmp') or not root.name.startswith('juanzhan-source-browser-'):
        raise ValueError('Expected an isolated browser fixture')
    root.mkdir(mode=0o755)
    for name in ('collection', 'flat', 'adoption'):
        (root / name).mkdir(mode=0o755)
    (root / 'collection' / '设计').mkdir(mode=0o755)
    (root / 'collection' / '设计' / '计划.txt').write_text('真实只读来源。\n', encoding='utf-8')
    (root / 'collection' / 'keep.txt').write_text('保留原件\n', encoding='utf-8')
    for index in range(31):
        (root / 'collection' / f'item-{index:02}.txt').write_text(f'content {index}\n')
    (root / 'flat' / 'one.txt').write_text('flat fixture\n')
    (root / 'adoption' / 'one.txt').write_text('adoption fixture\n')
    (root / 'collection' / 'ignored.bin').write_bytes(b'not a supported candidate')
    # The cloud shell uses umask 077; the unprivileged container needs read/traverse.
    for item in [root, *root.rglob('*')]:
        item.chmod(0o755 if item.is_dir() else 0o644)
    name = 'juanzhan-source-browser-' + uuid.uuid4().hex[:12]
    volume = name + '-data'
    stop = False
    def shutdown(*_):
        nonlocal stop
        stop = True
    signal.signal(signal.SIGTERM, shutdown)
    signal.signal(signal.SIGINT, shutdown)
    worker = None
    try:
        docker('volume', 'create', volume)
        docker('run', '-d', '--name', name, '-p', '127.0.0.1:8768:8000',
               '--mount', f'type=bind,source={root},target=/sources/fixtures,readonly',
               '--mount', f'type=bind,source={root},target=/sources/writable',
               '--mount', f'type=volume,source={volume},target=/data',
               '-e', 'JUANZHAN_DATA_DIR=/data', '-e', 'JUANZHAN_COOKIE_SECURE=false',
               '-e', 'JUANZHAN_SOURCE_MOUNTS=' + json.dumps({
                   'collection': '/sources/fixtures/collection', 'flat': '/sources/fixtures/flat',
                   'adoption': '/sources/fixtures/adoption',
                   'writable': '/sources/writable', 'offline': '/sources/fixtures/absent'}),
               os.environ.get('JUANZHAN_E2E_IMAGE','juanzhan-foundation:dev'))
        for _ in range(100):
            if stop:
                return
            try:
                with urllib.request.urlopen('http://127.0.0.1:8768/healthz', timeout=1) as response:
                    if response.status == 200:
                        break
            except OSError:
                time.sleep(.1)
        else:
            raise RuntimeError('Source browser API did not start')
        docker('exec', '-i', name, 'python', '-m', 'juanzhan.admin', 'set-password', '--stdin', input=os.environ['JUANZHAN_E2E_PASSWORD'] + '\n')
        worker = subprocess.Popen(['docker', 'exec', name, 'python', '-m', 'juanzhan.worker', '--poll-seconds', '0.05'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        # Playwright waits for this endpoint to ensure password and worker startup are done.
        from http.server import BaseHTTPRequestHandler, HTTPServer
        class Ready(BaseHTTPRequestHandler):
            def do_GET(self):
                self.send_response(200)
                self.end_headers()
                self.wfile.write(b'ready')
            def log_message(self, *_):
                pass
        server = HTTPServer(('127.0.0.1', 8769), Ready)
        server.timeout = .2
        while not stop:
            if worker.poll() is not None:
                raise RuntimeError('Browser fixture worker stopped')
            server.handle_request()
        server.server_close()
    finally:
        docker('rm', '-f', name)
        if worker:
            worker.wait(timeout=10)
        docker('volume', 'rm', volume)
        shutil.rmtree(root)


if __name__ == '__main__':
    main()
